-- =============================================================================
-- Carga del Analisis de riesgo de FINANZAS (Supervisor de finanzas), tomado de su formato en Excel, completado (fechas, acciones, detección y vinculado con).
-- Lo deja a nombre del usuario con puesto "Supervisor de finanzas" (si hay varios, el que se llame Nancy).
-- Si ya se habia cargado, lo ACTUALIZA (mismo folio). Despues se edita normal desde el portal.
-- Como aplicarlo: pega este archivo COMPLETO en SQL Editor y presiona Run.
-- =============================================================================
do $carga$
declare v_id uuid; v_ar uuid;
begin
  select id into v_id from public.profiles
   where rol = 'supervisor_finanzas' and activo
   order by (nombre ilike '%nancy%') desc, created_at limit 1;
  if v_id is null then raise exception 'No encontre a nadie con el puesto Supervisor de finanzas en el portal'; end if;
  -- Se registra como si lo hubiera capturado ella (autor y area).
  perform set_config('request.jwt.claim.sub', v_id::text, true);
  perform set_config('request.jwt.claims', json_build_object('sub', v_id, 'role', 'authenticated')::text, true);
  select id into v_ar from public.riesgo_analisis where created_by = v_id and proceso = 'Finanzas' order by created_at limit 1;
  if v_ar is null then
    insert into public.riesgo_analisis (proceso, fecha, actividades, created_by)
    values ('Finanzas', public.local_today(), $json$[{"id": "6sea3xae0pjo", "actividad": "Actualizar tipo de cambio", "modos": [{"id": "9c8q3qn4w34q", "modo": "Poner un tipo de cambio erróneo", "efectos": "Cotizaciones erróneas por parte de ventas", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 2, "causas": "Error en captura, falta de atención", "ocurrencia": 4, "prevencion": "Una segunda revisión", "deteccion_ctrl": "N/A", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "nsszmyswfl74", "actividad": "Revisión de bancos", "modos": [{"id": "pgdth4yutni3", "modo": "Que no se revisen los bancos", "efectos": "No se cuenta con información para la conciliación o confirmación de pagos de clientes que requieren certeza de su pago para surtirles", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 2, "causas": "Inasistencia de la(s) persona(s) encargada(s) del proceso, desconocimiento del uso de dispositivos o claves", "ocurrencia": 1, "prevencion": "El proceso lo deben saber al menos 2 personas; conocimiento de claves", "deteccion_ctrl": "N/A", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "ji6dwq2ng2yh", "actividad": "Recepción de facturas para realización de póliza de ingreso", "modos": [{"id": "suula2c3llrc", "modo": "Información rezagada", "efectos": "Retraso en el cierre mensual, falta de información para el cálculo de comisiones, falta de liquidez", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Los vendedores no identifican los pagos de sus clientes; desidia o falta de tiempo del vendedor para la entrega", "ocurrencia": 5, "prevencion": "N/A", "deteccion_ctrl": "N/A", "deteccion": 3, "acciones": "1) Fecha límite semanal para que ventas entregue las facturas y la identificación de los pagos de sus clientes. 2) Que cada vendedor marque en su bitácora del portal la venta como cobrada, con la referencia del pago, a más tardar 2 días después de recibirlo. 3) Enviar cada viernes a la jefa de ventas la lista de pagos sin identificar para que se resuelvan antes del cierre.", "responsable": "Supervisor de finanzas; jefa de ventas para que ventas cumpla", "fecha_terminacion": "2026-12-17", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "hmoljjj4hue2", "actividad": "Ingresos", "modos": [{"id": "heq9lfu8y345", "modo": "Pago aplicado a cliente incorrecto", "efectos": "Cancelaciones de complementos, cancelación de pólizas, mala experiencia con el cliente, retraso en el cierre", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 3, "causas": "Pagos del mismo monto", "ocurrencia": 3, "prevencion": "N/A", "deteccion_ctrl": "Conciliación", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "aoj1seies209", "modo": "Monto incorrecto del pago aplicado a cuentas por cobrar", "efectos": "Cancelaciones de complementos, cancelación de pólizas, retraso en el cierre", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 2, "causas": "Descuido al momento de la captura por parte de la persona que captura el pago", "ocurrencia": 1, "prevencion": "N/A", "deteccion_ctrl": "Conciliación", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "6572nwym7mg8", "actividad": "Pago de servicios", "modos": [{"id": "a10zlsaygpl8", "modo": "Corte del servicio", "efectos": "Corte de servicios", "vinculado": "Infraestructura", "tipo": "riesgo", "severidad": 2, "causas": "No llegan los recibos, mala calendarización", "ocurrencia": 1, "prevencion": "Calendario", "deteccion_ctrl": "N/A", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "f9tu43zut9c8", "actividad": "Cuentas por pagar", "modos": [{"id": "j290s6k9w61t", "modo": "Pago duplicado a proveedor", "efectos": "Pérdida económica directa, afectación al flujo, incremento de cuentas por pagar, hallazgo en auditoría, desconfianza del proveedor por reprocesos", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 2, "causas": "No hay un solo receptor de facturas ni un solo canal de pago", "ocurrencia": 3, "prevencion": "N/A", "deteccion_ctrl": "Conciliación", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "mttbjwcnlnkh", "modo": "Pago fuera de tiempo", "efectos": "Pago de intereses moratorios y recargos, suspensión de líneas de crédito, paro de suministro de materiales, afectación a los procesos operativos, calificación negativa del proveedor", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "Saldos insuficientes; facturas no detectadas porque no hay un solo receptor de facturas", "ocurrencia": 2, "prevencion": "N/A", "deteccion_ctrl": "Llamada o correo del proveedor cobrando la factura", "deteccion": 1, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "fe3cat4aum7j", "modo": "Captura errónea del monto o de la cuenta", "efectos": "Estados financieros incorrectos, balance general descuadrado, toma de decisiones errónea, pago incorrecto, diferencias en conciliación, auditoría con observaciones", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 2, "causas": "Descuido de la persona de pagos", "ocurrencia": 2, "prevencion": "N/A", "deteccion_ctrl": "Conciliación", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "fw2cs1by0zlv", "actividad": "Cuentas por cobrar", "modos": [{"id": "3ffymr93968e", "modo": "No se cobra a tiempo y se vence la cartera", "efectos": "Falta de liquidez, aumento del DSO (días de cartera), incremento de cartera incobrable, necesidad de financiamiento externo, costo financiero adicional", "vinculado": "Cliente", "tipo": "riesgo", "severidad": 4, "causas": "Tiempos muy permisivos por parte de los vendedores, falta de seguimiento a la deuda", "ocurrencia": 1, "prevencion": "N/A", "deteccion_ctrl": "Estados de cuenta", "deteccion": 4, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "n9qtfuxvnwzx", "actividad": "Tesorería / bancos", "modos": [{"id": "a0hz7mc4hx60", "modo": "Transferencia a cuenta equivocada", "efectos": "Pérdida de dinero irreversible, riesgo de fraude y suplantación, impacto legal por intento de recuperación, falta de pago al beneficiario real, retraso operativo", "vinculado": "Proveedor", "tipo": "riesgo", "severidad": 3, "causas": "Nombres de proveedores muy similares o descuido de la persona de pagos", "ocurrencia": 2, "prevencion": "N/A", "deteccion_ctrl": "Captura de póliza", "deteccion": 3, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "vnhdreu1dpb4", "modo": "Falta de liquidez para nómina o pagos críticos", "efectos": "Imposibilidad de pagar nóminas, paro de operaciones, demandas laborales, pérdida de confianza del personal, incumplimiento con pagos críticos (SAT, IMSS, proveedores)", "vinculado": "Personal", "tipo": "riesgo", "severidad": 3, "causas": "Saldos insuficientes por baja cobranza", "ocurrencia": 1, "prevencion": "N/A", "deteccion_ctrl": "Revisión de cobranza y saldos", "deteccion": 4, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "3toz6enqn6li", "modo": "No conciliar bancos y no detectar fraudes", "efectos": "Cargos bancarios no reconocidos o no detectados, fraudes cibernéticos no identificados, descuadre entre libros y bancos, hallazgos de auditorías externas, estados financieros no confiables", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 5, "causas": "Pagos no identificados por las áreas de ventas y finanzas; deshonestidad de personas de pagos", "ocurrencia": 4, "prevencion": "N/A", "deteccion_ctrl": "Conciliación", "deteccion": 4, "acciones": "1) Implementar acciones de sanción con vendedores que no identifiquen los pagos de sus clientes. 2) Conciliar los bancos cada semana (no solo al cierre) y revisar los cargos no reconocidos el mismo día. 3) Separar funciones: quien registra o hace los pagos no es quien concilia. 4) Doble autorización para transferencias y para altas o cambios de cuentas bancarias de proveedores.", "responsable": "Supervisor de finanzas; jefa de ventas para las sanciones; gerente para la doble autorización", "fecha_terminacion": "2026-12-17", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "p5ihmla8c98g", "actividad": "Nómina", "modos": [{"id": "09iv79xdsj5s", "modo": "Falta de pago a empleados", "efectos": "Molestia de los empleados, demandas ante conciliación y arbitraje", "vinculado": "Personal", "tipo": "riesgo", "severidad": 3, "causas": "Saldos en cuentas insuficientes, falla de la banca electrónica", "ocurrencia": 1, "prevencion": "Bancos de respaldo", "deteccion_ctrl": "Revisión de cobranza y saldos", "deteccion": 2, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "j0dig8oveure", "modo": "Pago de más o de menos a un empleado", "efectos": "Molestia de los empleados, demandas ante conciliación y arbitraje", "vinculado": "Personal", "tipo": "riesgo", "severidad": 3, "causas": "Error de captura", "ocurrencia": 1, "prevencion": "La misma banca da los totales, que deben coincidir con el monto de la nómina calculada", "deteccion_ctrl": "La misma banca da los totales, que deben coincidir con el monto de la nómina calculada", "deteccion": 1, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}]}, {"id": "2k9cm6xzj5gp", "actividad": "Cierre contable y fiscal", "modos": [{"id": "043xn9p35fn3", "modo": "Póliza mal registrada / cuenta contable incorrecta", "efectos": "Estados financieros incorrectos, decisiones de dirección basadas en información errónea, observaciones en auditoría financiera, reclasificaciones contables masivas", "vinculado": "Proceso", "tipo": "riesgo", "severidad": 3, "causas": "Error en captura, confusión en la asignación de cuentas contables", "ocurrencia": 4, "prevencion": "Conciliación", "deteccion_ctrl": "Conciliación", "deteccion": 1, "acciones": "", "responsable": "", "fecha_terminacion": "", "fecha_verificacion": "", "acciones_tomadas": "", "severidad_r": null, "ocurrencia_r": null, "deteccion_r": null}, {"id": "fimjxn4qv3y7", "modo": "Declaración mensual presentada fuera de tiempo", "efectos": "Multas y recargos del SAT, opinión de cumplimiento negativa, posibles bloqueos digitales, restricción para facturar", "vinculado": "Requisito legal", "tipo": "riesgo", "severidad": 5, "causas": "Cierres tardíos, errores u omisión de la d